sys_variable_value.value:
(function execute(inputs, outputs) {

    // Defaults
    outputs.bias_check_passed = false;
    outputs.integrity_check_passed = false;
    outputs.flagged_terms = "";
    outputs.integrity_issues = "";
    outputs.ai_additional_comments = "";
    outputs.parse_success = false;
    outputs.parse_error = "";

    try {
        var response = inputs.ai_response;
        var data;

        if (response === null || response === undefined) {
            throw new Error("AI response is empty.");
        }

        // --------------------------------------------------------
        // 1. If ServiceNow already gives us an object, use it.
        // --------------------------------------------------------
        if (typeof response === "object" && !Array.isArray(response)) {
            data = response;

        } else {

            var text = String(response).trim();

            if (!text) {
                throw new Error("AI response is empty.");
            }

            // ----------------------------------------------------
            // 2. Remove Markdown code fences
            // ----------------------------------------------------
            text = text
                .replace(/^```(?:json)?\s*/i, "")
                .replace(/\s*```\s*$/i, "")
                .trim();

            // ----------------------------------------------------
            // 3. Parse directly if the whole response is JSON.
            // ----------------------------------------------------
            try {
                data = JSON.parse(text);

            } catch (directError) {

                // ------------------------------------------------
                // 4. Find JSON object inside surrounding AI text.
                //
                // Unlike indexOf/lastIndexOf, this understands:
                // - nested {}
                // - quoted strings
                // - escaped quotes
                // - braces inside strings
                // ------------------------------------------------
                var start = -1;
                var depth = 0;
                var inString = false;
                var escaped = false;

                for (var i = 0; i < text.length; i++) {

                    var ch = text.charAt(i);

                    if (start === -1) {
                        if (ch === "{") {
                            start = i;
                            depth = 1;
                        }
                        continue;
                    }

                    if (inString) {
                        if (escaped) {
                            escaped = false;
                        } else if (ch === "\\") {
                            escaped = true;
                        } else if (ch === "\"") {
                            inString = false;
                        }
                        continue;
                    }

                    if (ch === "\"") {
                        inString = true;
                    } else if (ch === "{") {
                        depth++;
                    } else if (ch === "}") {
                        depth--;

                        if (depth === 0) {
                            break;
                        }
                    }
                }

                if (start === -1 || depth !== 0) {
                    throw new Error("No complete JSON object found.");
                }

                var jsonText = text.substring(start, i + 1);

                try {
                    data = JSON.parse(jsonText);
                } catch (jsonError) {
                    throw new Error(
                        "JSON parsing failed: " + jsonError.message
                    );
                }
            }
        }

        // --------------------------------------------------------
        // 5. Validate the JSON structure
        // --------------------------------------------------------

        if (
            !data ||
            typeof data !== "object" ||
            Array.isArray(data)
        ) {
            throw new Error("AI response is not a JSON object.");
        }

        if (typeof data.bias_check_passed !== "boolean") {
            throw new Error(
                "bias_check_passed must be Boolean."
            );
        }

        if (typeof data.integrity_check_passed !== "boolean") {
            throw new Error(
                "integrity_check_passed must be Boolean."
            );
        }

        if (!Array.isArray(data.flagged_terms)) {
            throw new Error(
                "flagged_terms must be an Array."
            );
        }

        if (!Array.isArray(data.integrity_issues)) {
            throw new Error(
                "integrity_issues must be an Array."
            );
        }

        // --------------------------------------------------------
        // 6. Convert arrays to bullet-point strings
        // --------------------------------------------------------

        function toBullets(items) {
            return items
                .filter(function(item) {
                    return item !== null &&
                           item !== undefined &&
                           String(item).trim() !== "";
                })
                .map(function(item) {
                    return "• " + String(item).trim();
                })
                .join("\n");
        }

        // --------------------------------------------------------
        // 7. Set Flow outputs
        // --------------------------------------------------------

        outputs.bias_check_passed =
            data.bias_check_passed;

        outputs.integrity_check_passed =
            data.integrity_check_passed;

        outputs.flagged_terms =
            toBullets(data.flagged_terms);

        outputs.integrity_issues =
            toBullets(data.integrity_issues);

        outputs.ai_additional_comments =
            data.ai_additional_comments == null
                ? ""
                : String(data.ai_additional_comments).trim();

        outputs.parse_success = true;
        outputs.parse_error = "";

    } catch (e) {

        outputs.parse_success = false;
        outputs.parse_error =
            e.message || String(e);
    }

})(inputs, outputs);

